// zfa:tdd: A3:hand — hand step completed before first red certification (issue #1411)
//
// Hand-completed acceptance test for A3 (AC-3, issue
// arrrrny/zuraffa_browser#168): a widget on a route pushed onto the shell's
// navigator resolves the shell's ScaffoldMessenger — no "No ScaffoldMessenger
// widget found" throw.
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zuraffa_ui/tdd/shadapp-missing-scaffoldmessenger/a3_subject.dart'
    as subject;

void main() {
  group('A3 (AC-3)', () {
    testWidgets('A3 — it resolves the shell\'s messenger without throwing.', (
      tester,
    ) async {
      final messenger = await subject.subject_a3(tester);

      // The observable outcome (issue #1488): the messenger resolved from the
      // pushed route — asserted outside the guard.
      expect(messenger, isA<ScaffoldMessengerState>());
      expect(messenger.mounted, isTrue);
    });
  });
}

// zfa:tdd: A3:hand — hand step completed before first red certification (issue #1411)
//
// Hand-implemented scenario runner for behavior A3 (AC-3): pushes a route onto
// ZuraffaApp's navigator and resolves the shell's ScaffoldMessenger from the
// pushed route's context.
//
// The subject name is derived from the behavior id (`subject_a3`) and is
// deliberately snake_cased — the generator KNOWS the name it emits, so the
// lint its shape provably trips is suppressed here rather than renaming the
// contract surface (issue #1035).
// ignore_for_file: non_constant_identifier_names
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zuraffa_ui/zuraffa_ui.dart';

/// Runs the A3 scenario: mounts the shell, pushes a named route, and returns
/// the [ScaffoldMessengerState] resolved from the pushed route's context.
///
/// Throws if the shell provides no `ScaffoldMessenger` ancestor — the
/// condition reported in arrrrny/zuraffa_browser#168.
Future<ScaffoldMessengerState> subject_a3(WidgetTester tester) async {
  late BuildContext routeContext;
  await tester.pumpWidget(
    ZuraffaApp(
      showViolationChrome: false,
      home: Scaffold(
        body: Builder(
          builder: (context) => ZfaButton(
            child: const Text('open probe route'),
            onPressed: () => Navigator.of(context).push(
              MaterialPageRoute<void>(
                settings: const RouteSettings(name: 'zfa.probe'),
                builder: (context) {
                  routeContext = context;
                  return const Scaffold(body: Text('probe route'));
                },
              ),
            ),
          ),
        ),
      ),
    ),
  );
  await tester.tap(find.text('open probe route'));
  await tester.pumpAndSettle();
  return ScaffoldMessenger.of(routeContext);
}
